package com.intelligentrecruitment.notifications.api;
import com.intelligentrecruitment.notifications.application.NotificationService;import com.intelligentrecruitment.shared.security.CurrentUser;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import java.util.UUID;
@RestController @RequestMapping("/api/v1/notifications") public class NotificationController{private final NotificationService service;public NotificationController(NotificationService service){this.service=service;}@GetMapping NotificationService.Page list(@RequestParam(defaultValue="50") int limit,Authentication a){return service.list(CurrentUser.id(a),limit);}@PostMapping("/{id}/read")void read(@PathVariable UUID id,Authentication a){service.markRead(CurrentUser.id(a),id);}@PostMapping("/read-all")void readAll(Authentication a){service.markAllRead(CurrentUser.id(a));}}
